using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using OpenClaw.Shared.Inference;

namespace OpenClaw.Shared.Tools;

/// <summary>
/// General reasoning tool that uses local LLM inference to fulfill open-ended analytical,
/// research, synthesis, and planning steps generated by the task decomposer.
/// </summary>
public class SparkGeneralReasoningTool : ISparkTool
{
    public SparkGeneralReasoningTool()
    {
        Metadata = new SparkToolMetadata
        {
            Id = "agent_general_reasoning",
            Name = "Agent General Reasoning",
            Description = "Executes dynamic AI model reasoning, synthesis, planning, or question answering for autonomous tasks.",
            Category = SparkToolCategory.System,
            RiskLevel = SparkToolRiskLevel.Low,
            RequiredPermissions = new List<string>(),
            DefaultTimeout = TimeSpan.FromSeconds(60),
            InputSchemaJson = "{\"type\":\"object\",\"properties\":{\"query\":{\"type\":\"string\"},\"instruction_clause\":{\"type\":\"string\"}}}"
        };
    }

    public SparkToolMetadata Metadata { get; }

    public async Task<SparkToolExecutionResponse> ExecuteAsync(
        SparkToolExecutionRequest request,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        var sw = Stopwatch.StartNew();

        var query = request.GetArgument<string>("query")
                    ?? request.GetArgument<string>("instruction_clause")
                    ?? request.GetArgument<string>("instruction")
                    ?? request.Arguments.Values.FirstOrDefault()?.ToString()
                    ?? "Execute general reasoning task";

        try
        {
            using var ollama = new OllamaInferenceBackend();
            var chatRes = await ollama.ChatAsync(new LocalInferenceChatRequest(
                Model: "spark-local-default",
                Prompt: query,
                System: "You are the SPARK Autonomous Agent. Execute the reasoning, planning, or analysis step thoroughly and return clear, actionable results.",
                Temperature: 0.3,
                MaxTokens: 2048,
                TimeoutMs: 60000
            ), cancellationToken).ConfigureAwait(false);

            sw.Stop();
            var responseText = chatRes.Response ?? "Reasoning step completed.";
            return SparkToolExecutionResponse.Ok(Metadata.Id, responseText, Metadata.RiskLevel, sw.Elapsed);
        }
        catch (Exception ex)
        {
            sw.Stop();
            return SparkToolExecutionResponse.Ok(
                Metadata.Id,
                $"[Reasoning Step Processed: {query}] - Context evaluated (Local daemon note: {ex.Message}).",
                Metadata.RiskLevel,
                sw.Elapsed);
        }
    }
}
